// The supported D2FPS image replaces Client +44E51..+44E9A with eight
// NOPs, CALL D2FPS +E710 at +44E59, EB 3A, then 58 NOPs. Its call target
// is checked against the loaded, hash-verified D2FPS base, not wildcarded.
// The callback at +44E2F is earlier than both the native and D2FPS player
// snapshots. Preserve the whole replacement and its native resume point.
inline constexpr uint32_t reveal_before_scene_fps_call=0x44e59;
inline constexpr uint32_t reveal_before_scene_fps_draw=0xe710;
inline constexpr auto reveal_before_scene_fps_sites=[] {
    std::array<RevealSite,4> sites{};
    for(uint32_t i=0;i<sites.size();++i){sites[i].module=L"D2Client.dll";sites[i].rva=0x44e34+i*32;}
    for(uint32_t i=0;i<102;++i){
        sites[i/32].bytes[i%32]=i<29?reveal_before_scene_sites[0].bytes[i]:0x90;
        sites[i/32].mask[i%32]=0xff;
    }
    sites[37/32].bytes[37%32]=0xe8;
    for(uint32_t i=38;i<42;++i)sites[i/32].mask[i%32]=0;
    sites[42/32].bytes[42%32]=0xeb;sites[43/32].bytes[43%32]=0x3a;
    return sites;
}();
